  expected_inserts constant integer := 3;
  expected_stints constant integer := 383;
  expected_rows_2026 constant integer := 5862;
  hash_before constant text := '68e6de0f412a38bc73aaa77c2cf8c449';
  hash_after constant text := 'a61b897f49fe9fc567b55a1e52208ad7';
